use anyhow::{anyhow, Context, Result};
use clap::{Arg, Command};
use std::fs::{self, File};
use std::io::{self, Read, Write, BufReader, BufWriter};
use std::path::{Path, PathBuf};
use zstd::Decoder as ZstdDecoder;
use zstd::Encoder as ZstdEncoder;

const VERSION: &str = "1.6.0";

fn main() -> Result<()> {
    let matches = build_cli().get_matches();

    // Get basic options
    let compress_level: u32 = if matches.contains_id("COMPRESSION_LEVEL") {
        matches.get_one::<String>("COMPRESSION_LEVEL")
            .ok_or(anyhow!("Invalid compression level"))?
            .parse()?
    } else {
        3
    };

    let to_stdout = matches.get_flag("stdout");
    let decompress = matches.get_flag("decompress");
    let keep = matches.get_flag("keep") || !matches.get_flag("rm");
    let force = matches.get_flag("force");
    let verbose = matches.get_flag("verbose");
    let quiet = matches.get_flag("quiet");
    let test_only = matches.get_flag("test");
    let list_info = matches.get_flag("list");
    let show_help = matches.get_flag("help");
    let show_version = matches.get_flag("version");
    let output_file = matches.get_one::<String>("output").map(|s| s.as_str());

    // Handle version flag
    if show_version {
        println!("*** Zstandard CLI (64-bit) v{}, by Yann Collet ***", VERSION);
        return Ok(());
    }

    // Handle help flag
    if show_help {
        println!("{}", build_cli().render_help());
        return Ok(());
    }

    // Get input files
    let input_files: Vec<&String> = matches.get_many::<String>("INPUT")
        .map(|v| v.collect())
        .unwrap_or_default();

    // Handle list info
    if list_info {
        for file in &input_files {
            list_file_info(file)?;
        }
        return Ok(());
    }

    // Handle test only
    if test_only {
        for file in &input_files {
            test_file(file)?;
        }
        return Ok(());
    }

    // Determine if reading from stdin
    let has_input_files = !input_files.is_empty() && input_files[0] != "-";

    if to_stdout {
        if has_input_files {
            for file in &input_files {
                if decompress {
                    decompress_file_to_stdout(file)?;
                } else {
                    compress_file_to_stdout(file, compress_level)?;
                }
            }
        } else {
            // Read from stdin and write to stdout
            if decompress {
                decompress_stdin_to_stdout()?;
            } else {
                compress_stdin_to_stdout(compress_level)?;
            }
        }
    } else if let Some(output) = output_file {
        // Single output file mode
        if input_files.is_empty() || input_files[0] == "-" {
            // Read from stdin, write to output
            if decompress {
                decompress_stdin_to_file(output)?;
            } else {
                compress_stdin_to_file(output, compress_level)?;
            }
        } else if input_files.len() == 1 {
            // Single input file to single output file
            if decompress {
                decompress_file_to_file(&input_files[0], output)?;
            } else {
                compress_file_to_file(&input_files[0], output, compress_level)?;
            }
        } else {
            return Err(anyhow!("Cannot use -o with multiple input files"));
        }
    } else {
        // Default mode: process files normally
        if has_input_files {
            for file in &input_files {
                if decompress {
                    let output_name = if file.ends_with(".zst") {
                        file[..file.len() - 4].to_string()
                    } else {
                        format!("{}.decompressed", file)
                    };
                    decompress_file_to_file(file, &output_name)?;
                    if !keep {
                        fs::remove_file(file)?;
                    }
                } else {
                    let output_name = format!("{}.zst", file);
                    compress_file_to_file(file, &output_name, compress_level)?;
                    if !keep {
                        fs::remove_file(file)?;
                    }
                }
            }
        } else {
            // Read from stdin
            if decompress {
                decompress_stdin_to_stdout()?;
            } else {
                compress_stdin_to_stdout(compress_level)?;
            }
        }
    }

    Ok(())
}

fn build_cli() -> Command {
    Command::new("zstd")
        .about("Zstandard compression tool")
        .arg(
            Arg::new("INPUT")
                .help("Input files to compress/decompress")
                .num_args(0..)
                .trailing_var_arg(true)
        )
        .arg(
            Arg::new("COMPRESSION_LEVEL")
                .help("Compression level (1-19)")
                .value_parser(clap::value_parser!(String))
                .hide(true)
        )
        .arg(
            Arg::new("output")
                .short('o')
                .help("Output file")
        )
        .arg(
            Arg::new("keep")
                .short('k')
                .long("keep")
                .help("Keep input file")
                .action(clap::ArgAction::SetTrue)
                .default_value("true")
        )
        .arg(
            Arg::new("rm")
                .long("rm")
                .help("Remove input file after compression")
                .action(clap::ArgAction::SetTrue)
        )
        .arg(
            Arg::new("stdout")
                .short('c')
                .long("stdout")
                .help("Write to stdout")
                .action(clap::ArgAction::SetTrue)
        )
        .arg(
            Arg::new("decompress")
                .short('d')
                .long("decompress")
                .help("Decompress")
                .action(clap::ArgAction::SetTrue)
        )
        .arg(
            Arg::new("verbose")
                .short('v')
                .long("verbose")
                .help("Verbose output")
                .action(clap::ArgAction::Count)
        )
        .arg(
            Arg::new("quiet")
                .short('q')
                .long("quiet")
                .help("Quiet output")
                .action(clap::ArgAction::Count)
        )
        .arg(
            Arg::new("force")
                .short('f')
                .long("force")
                .help("Force overwrite")
                .action(clap::ArgAction::SetTrue)
        )
        .arg(
            Arg::new("test")
                .short('t')
                .help("Test file integrity")
                .action(clap::ArgAction::SetTrue)
        )
        .arg(
            Arg::new("list")
                .short('l')
                .help("List file information")
                .action(clap::ArgAction::SetTrue)
        )
        .arg(
            Arg::new("help")
                .short('H')
                .long("help")
                .help("Show help")
                .action(clap::ArgAction::SetTrue)
        )
        .arg(
            Arg::new("version")
                .short('V')
                .long("version")
                .help("Show version")
                .action(clap::ArgAction::SetTrue)
        )
}

fn compress_file_to_file(input: &str, output: &str, level: u32) -> Result<()> {
    let input_file = File::open(input)
        .context(format!("Failed to open input file: {}", input))?;
    let input_metadata = fs::metadata(input)?;
    let input_size = input_metadata.len();

    let output_file = File::create(output)
        .context(format!("Failed to create output file: {}", output))?;

    let mut encoder = ZstdEncoder::new(output_file, level as i32)?;
    let mut reader = BufReader::new(input_file);
    let mut buffer = vec![0u8; 65536];

    loop {
        let bytes_read = reader.read(&mut buffer)?;
        if bytes_read == 0 {
            break;
        }
        encoder.write_all(&buffer[..bytes_read])?;
    }

    let output_file = encoder.finish()?;
    let output_metadata = output_file.metadata()?;
    let output_size = output_metadata.len();
    let ratio = (output_size as f64 / input_size as f64) * 100.0;

    println!("{}  : {:.2}%   ( {} B =>  {} B, {} )", 
        input, ratio, input_size, output_size, output);

    Ok(())
}

fn compress_file_to_stdout(input: &str, level: u32) -> Result<()> {
    let input_file = File::open(input)?;
    let mut encoder = ZstdEncoder::new(io::stdout(), level as i32)?;
    let mut reader = BufReader::new(input_file);
    let mut buffer = vec![0u8; 65536];

    loop {
        let bytes_read = reader.read(&mut buffer)?;
        if bytes_read == 0 {
            break;
        }
        encoder.write_all(&buffer[..bytes_read])?;
    }

    encoder.finish()?;
    Ok(())
}

fn compress_stdin_to_stdout(level: u32) -> Result<()> {
    let mut encoder = ZstdEncoder::new(io::stdout(), level as i32)?;
    let stdin = io::stdin();
