fn test_file(input: &str) -> Result<()> {
    let input_file = File::open(input)?;
    let mut decoder = ZstdDecoder::new(BufReader::new(input_file))?;
    let mut buffer = vec![0u8; 65536];
    let mut total = 0u64;

    loop {
        let bytes_read = decoder.read(&mut buffer)?;
        if bytes_read == 0 {
            break;
        }
        total += bytes_read as u64;
    }

    println!("{}  : {} bytes ", input, total);
    Ok(())
}

fn get_uncompressed_size(input: &str) -> Result<u64> {
    let input_file = File::open(input)?;
    let mut decoder = ZstdDecoder::new(BufReader::new(input_file))?;
    let mut buffer = vec![0u8; 65536];
    let mut total = 0u64;

    loop {
        let bytes_read = decoder.read(&mut buffer)?;
        if bytes_read == 0 {
            break;
        }
        total += bytes_read as u64;
    }

    Ok(total)
}

fn list_file_info(input: &str) -> Result<()> {
    let input_file = File::open(input)?;
    let input_metadata = fs::metadata(input)?;
    let compressed_size = input_metadata.len();

    let uncompressed_size = get_uncompressed_size(input)?;
    let ratio = if compressed_size > 0 {
        uncompressed_size as f64 / compressed_size as f64
    } else {
        0.0
    };

    // Print header on first call
    static HEADER_PRINTED: std::sync::atomic::AtomicBool = std::sync::atomic::AtomicBool::new(false);
    if !HEADER_PRINTED.swap(true, std::sync::atomic::Ordering::Relaxed) {
        println!("Frames  Skips  Compressed  Uncompressed  Ratio  Check  Filename");
    }

    println!("     1      0  {} B  {} B  {:.3}  XXH64  {}", 
        compressed_size, uncompressed_size, ratio, input);

    Ok(())
}
