fn main() -> Result<(), Box<dyn std::error::Error>> {
    let args: Vec<String> = env::args().collect();

    let mut opts = Options::default();
    let mut input_files: Vec<String> = Vec::new();
    let mut i = 1;

    while i < args.len() {
        let arg = &args[i];

        match arg.as_str() {
            "--version" | "-V" => {
                println!("*** Zstandard CLI (64-bit) v1.6.0, by Yann Collet ***");
                return Ok(());
            }
            "-h" | "--help" | "-H" => {
                print_help();
                return Ok(());
            }
            "-d" | "--decompress" => opts.decompress = true,
            "-c" | "--stdout" => opts.to_stdout = true,
            "-k" | "--keep" => opts.keep = true,
            "--rm" => opts.keep = false,
            "-f" | "--force" => opts.force = true,
            "-t" => opts.test_only = true,
            "-l" => opts.list_info = true,
            "-v" | "--verbose" => opts.verbose += 1,
            "-q" | "--quiet" => opts.quiet += 1,
            "-o" => {
                i += 1;
                if i < args.len() {
                    opts.output_file = Some(args[i].clone());
                }
            }
            "-D" => {
                i += 1;
                if i < args.len() {
                    opts.dict_file = Some(args[i].clone());
                }
            }
            arg if arg.starts_with("-") && arg.len() == 2 && arg.chars().nth(1).unwrap().is_ascii_digit() => {
                // Compression level like -5
                opts.compression_level = arg[1..].parse()?;
            }
            arg if arg.starts_with("-") && arg.len() > 2 && arg.chars().nth(1).unwrap().is_ascii_digit() => {
                // Compression level like -19
                opts.compression_level = arg[1..].parse()?;
            }
            _ => input_files.push(arg.clone()),
        }

        i += 1;
    }

