fn compress_data(data: &[u8], level: i32) -> Result<Vec<u8>, Box<dyn std::error::Error>> {
    unsafe {
        let cctx = zstd_ffi::ZSTD_createCCtx();
        if cctx.is_null() {
            return Err("Failed to create compression context".into());
        }

        let max_output_size = data.len() + 100;
        let mut output = vec![0u8; max_output_size];

        let result = zstd_ffi::ZSTD_compressCCtx(
            cctx,
            output.as_mut_ptr() as *mut std::os::raw::c_void,
            output.len() as u64,
            data.as_ptr() as *const std::os::raw::c_void,
            data.len() as u64,
            level,
        );

        zstd_ffi::ZSTD_freeCCtx(cctx);

        if zstd_ffi::ZSTD_isError(result) != 0 {
            let error_name = zstd_ffi::ZSTD_getErrorName(result);
            let error_str = std::ffi::CStr::from_ptr(error_name as *const i8).to_string_lossy();
            return Err(format!("Compression error: {}", error_str).into());
        }

        output.truncate(result as usize);
        Ok(output)
    }
}

fn decompress_data(data: &[u8]) -> Result<Vec<u8>, Box<dyn std::error::Error>> {
    unsafe {
        let dctx = zstd_ffi::ZSTD_createDCtx();
        if dctx.is_null() {
            return Err("Failed to create decompression context".into());
        }

        // Try to get frame content size
        let frame_size = zstd_ffi::ZSTD_getFrameContentSize(
            data.as_ptr() as *const std::os::raw::c_void,
            data.len() as u64,
        );

        let output_size = if frame_size == u64::MAX || frame_size == 0 {
            data.len() * 4 // Default estimate
        } else {
            frame_size as usize
        };

        let mut output = vec![0u8; output_size];

        let result = zstd_ffi::ZSTD_decompressDCtx(
            dctx,
            output.as_mut_ptr() as *mut std::os::raw::c_void,
            output.len() as u64,
            data.as_ptr() as *const std::os::raw::c_void,
            data.len() as u64,
        );

        zstd_ffi::ZSTD_freeDCtx(dctx);

        if zstd_ffi::ZSTD_isError(result) != 0 {
            let error_name = zstd_ffi::ZSTD_getErrorName(result);
            let error_str = std::ffi::CStr::from_ptr(error_name as *const i8).to_string_lossy();
            return Err(format!("Decompression error: {}", error_str).into());
        }

        output.truncate(result as usize);
        Ok(output)
    }
}
