fn compress_file_to_file(input: &str, output: &str, level: i32) -> Result<(), Box<dyn std::error::Error>> {
    let data = fs::read(input)?;
    let compressed = compress_data(&data, level)?;
    let input_size = data.len();
    let output_size = compressed.len();
    let ratio = (output_size as f64 / input_size as f64) * 100.0;

    fs::write(output, compressed)?;

    println!("{}  : {:.2}%   ( {} B =>  {} B, {} )", 
        input, ratio, input_size, output_size, output);

    Ok(())
}

fn compress_file_to_stdout(input: &str, level: i32) -> Result<(), Box<dyn std::error::Error>> {
    let data = fs::read(input)?;
    let compressed = compress_data(&data, level)?;
    io::stdout().write_all(&compressed)?;
    Ok(())
}

