fn main() -> Result<(), Box<dyn std::error::Error>> {
    let args: Vec<String> = env::args().collect();

    let mut opts = Options::default();
    let mut input_files: Vec<String> = Vec::new();
    let mut i = 1;

    while i < args.len() {
        let arg = &args[i];

        match arg.as_str() {
            "--version" | "-V" => {
                println!("*** Zstandard CLI (64-bit) v1.6.0, by Yann Collet ***");
                return Ok(());
            }
            "-h" | "--help" | "-H" => {
                print_help();
                return Ok(());
            }
            "-d" | "--decompress" => opts.decompress = true,
            "-c" | "--stdout" => opts.to_stdout = true,
            "-k" | "--keep" => opts.keep = true,
            "--rm" => opts.keep = false,
            "-f" | "--force" => opts.force = true,
            "-t" => opts.test_only = true,
            "-l" => opts.list_info = true,
            "-v" | "--verbose" => opts.verbose += 1,
            "-q" | "--quiet" => opts.quiet += 1,
            "-o" => {
                i += 1;
                if i < args.len() {
                    opts.output_file = Some(args[i].clone());
                }
            }
            "-D" => {
                i += 1;
                if i < args.len() {
                    opts.dict_file = Some(args[i].clone());
                }
            }
            arg if arg.starts_with("-") && arg.len() == 2 && arg.chars().nth(1).unwrap().is_ascii_digit() => {
                // Compression level like -5
                opts.compression_level = arg[1..].parse()?;
            }
            arg if arg.starts_with("-") && arg.len() > 2 && arg.chars().nth(1).unwrap().is_ascii_digit() => {
                // Compression level like -19
                opts.compression_level = arg[1..].parse()?;
            }
            _ => input_files.push(arg.clone()),
        }

        i += 1;
    }

    // Handle version and help
    if opts.list_info {
        for file in &input_files {
            list_file_info(file)?;
        }
        return Ok(());
    }

    if opts.test_only {
        for file in &input_files {
            test_file(file)?;
        }
        return Ok(());
    }

    // Determine if reading from stdin
    let has_input_files = !input_files.is_empty() && input_files[0] != "-";

    if opts.to_stdout {
        if has_input_files {
            for file in &input_files {
                if opts.decompress {
                    decompress_file_to_stdout(file)?;
                } else {
                    compress_file_to_stdout(file, opts.compression_level)?;
                }
            }
        } else {
            // Read from stdin and write to stdout
            if opts.decompress {
                decompress_stdin_to_stdout()?;
            } else {
                compress_stdin_to_stdout(opts.compression_level)?;
            }
        }
    } else if let Some(output) = &opts.output_file {
        // Single output file mode
        if input_files.is_empty() || input_files[0] == "-" {
            // Read from stdin, write to output
            if opts.decompress {
                decompress_stdin_to_file(output)?;
            } else {
                compress_stdin_to_file(output, opts.compression_level)?;
            }
        } else if input_files.len() == 1 {
            // Single input file to single output file
            if opts.decompress {
                decompress_file_to_file(&input_files[0], output)?;
            } else {
                compress_file_to_file(&input_files[0], output, opts.compression_level)?;
            }
        } else {
            return Err("Cannot use -o with multiple input files".into());
        }
    } else {
        // Default mode: process files normally
        if has_input_files {
            for file in &input_files {
                if opts.decompress {
                    let output_name = if file.ends_with(".zst") {
                        file[..file.len() - 4].to_string()
                    } else {
                        format!("{}.decompressed", file)
                    };
                    decompress_file_to_file(file, &output_name)?;
                    if !opts.keep {
                        fs::remove_file(file)?;
                    }
                } else {
                    let output_name = format!("{}.zst", file);
                    compress_file_to_file(file, &output_name, opts.compression_level)?;
                    if !opts.keep {
                        fs::remove_file(file)?;
                    }
                }
            }
        } else {
            // Read from stdin
            if opts.decompress {
                decompress_stdin_to_stdout()?;
            } else {
                compress_stdin_to_stdout(opts.compression_level)?;
            }
        }
    }

    Ok(())
}

