fn compress_file_to_file(input: &str, output: &str, level: i32, zstd: &zstd_dll::ZSTD) -> Result<(), Box<dyn std::error::Error>> {
    let data = fs::read(input)?;
    let compressed = zstd.compress(&data, level)?;
    let input_size = data.len();
    let output_size = compressed.len();
    let ratio = (output_size as f64 / input_size as f64) * 100.0;

    fs::write(output, compressed)?;

    println!("{}  : {:.2}%   ( {} B =>  {} B, {} )", 
        input, ratio, input_size, output_size, output);

    Ok(())
}

fn compress_file_to_stdout(input: &str, level: i32, zstd: &zstd_dll::ZSTD) -> Result<(), Box<dyn std::error::Error>> {
    let data = fs::read(input)?;
    let compressed = zstd.compress(&data, level)?;
    io::stdout().write_all(&compressed)?;
    Ok(())
}

fn compress_stdin_to_stdout(level: i32, zstd: &zstd_dll::ZSTD) -> Result<(), Box<dyn std::error::Error>> {
    let mut data = Vec::new();
    io::stdin().read_to_end(&mut data)?;
    let compressed = zstd.compress(&data, level)?;
    io::stdout().write_all(&compressed)?;
    Ok(())
}

fn compress_stdin_to_file(output: &str, level: i32, zstd: &zstd_dll::ZSTD) -> Result<(), Box<dyn std::error::Error>> {
    let mut data = Vec::new();
    io::stdin().read_to_end(&mut data)?;
    let compressed = zstd.compress(&data, level)?;
    fs::write(output, compressed)?;
    Ok(())
}

fn decompress_file_to_file(input: &str, output: &str, zstd: &zstd_dll::ZSTD) -> Result<(), Box<dyn std::error::Error>> {
    let compressed = fs::read(input)?;
    let decompressed = zstd.decompress(&compressed)?;
    fs::write(output, &decompressed)?;
    println!("{}  : {} bytes ", input, decompressed.len());
    Ok(())
}

fn decompress_file_to_stdout(input: &str, zstd: &zstd_dll::ZSTD) -> Result<(), Box<dyn std::error::Error>> {
    let compressed = fs::read(input)?;
    let decompressed = zstd.decompress(&compressed)?;
    io::stdout().write_all(&decompressed)?;
    Ok(())
}

fn decompress_stdin_to_stdout(zstd: &zstd_dll::ZSTD) -> Result<(), Box<dyn std::error::Error>> {
    let mut compressed = Vec::new();
    io::stdin().read_to_end(&mut compressed)?;
    let decompressed = zstd.decompress(&compressed)?;
    io::stdout().write_all(&decompressed)?;
    Ok(())
}

fn decompress_stdin_to_file(output: &str, zstd: &zstd_dll::ZSTD) -> Result<(), Box<dyn std::error::Error>> {
    let mut compressed = Vec::new();
    io::stdin().read_to_end(&mut compressed)?;
    let decompressed = zstd.decompress(&compressed)?;
    fs::write(output, decompressed)?;
    Ok(())
}

fn test_file(input: &str, zstd: &zstd_dll::ZSTD) -> Result<(), Box<dyn std::error::Error>> {
    let compressed = fs::read(input)?;
    let decompressed = zstd.decompress(&compressed)?;
    println!("{}  : {} bytes ", input, decompressed.len());
    Ok(())
}

fn list_file_info(input: &str, zstd: &zstd_dll::ZSTD) -> Result<(), Box<dyn std::error::Error>> {
    let compressed = fs::read(input)?;
    let decompressed = zstd.decompress(&compressed)?;
    let compressed_size = compressed.len();
    let uncompressed_size = decompressed.len();
    let ratio = if compressed_size > 0 {
        uncompressed_size as f64 / compressed_size as f64
    } else {
        0.0
    };

    static PRINTED: std::sync::atomic::AtomicBool = std::sync::atomic::AtomicBool::new(false);
    if !PRINTED.swap(true, std::sync::atomic::Ordering::Relaxed) {
        println!("Frames  Skips  Compressed  Uncompressed  Ratio  Check  Filename");
    }

    println!("     1      0  {} B  {} B  {:.3}  XXH64  {}", 
        compressed_size, uncompressed_size, ratio, input);

    Ok(())
}
