fn test_file(input: &str, zstd: &zstd_dll::ZSTD) -> Result<(), Box<dyn std::error::Error>> {
    let compressed = fs::read(input)?;
    let decompressed = zstd.decompress(&compressed)?;
    println!("{}  : {} bytes ", input, decompressed.len());
    Ok(())
}

fn list_file_info(input: &str, zstd: &zstd_dll::ZSTD) -> Result<(), Box<dyn std::error::Error>> {
    let compressed = fs::read(input)?;
    let decompressed = zstd.decompress(&compressed)?;
    let compressed_size = compressed.len();
    let uncompressed_size = decompressed.len();
    let ratio = if compressed_size > 0 {
        uncompressed_size as f64 / compressed_size as f64
    } else {
        0.0
    };

    static PRINTED: std::sync::atomic::AtomicBool = std::sync::atomic::AtomicBool::new(false);
    if !PRINTED.swap(true, std::sync::atomic::Ordering::Relaxed) {
        println!("Frames  Skips  Compressed  Uncompressed  Ratio  Check  Filename");
    }

    println!("     1      0  {} B  {} B  {:.3}  XXH64  {}", 
        compressed_size, uncompressed_size, ratio, input);

    Ok(())
}
