use std::env;
use std::fs;
use std::io::{self, Read, Write};
use std::ffi::{CStr, CString};
use std::os::raw::{c_void, c_int, c_ulonglong};

// Minimal libc bindings
mod libc_bindings {
    use std::os::raw::c_void;

    pub const RTLD_LAZY: i32 = 0x00001;
    pub const RTLD_GLOBAL: i32 = 0x00100;

    extern "C" {
        pub fn dlopen(filename: *const u8, flags: i32) -> *mut c_void;
        pub fn dlsym(handle: *mut c_void, symbol: *const u8) -> *mut c_void;
        pub fn dlerror() -> *const u8;
    }
}

mod zstd_dll {
    use std::ffi::{CStr, CString};
    use std::os::raw::{c_void, c_int, c_ulonglong};
    use std::ptr;

    pub struct ZSTD {
        lib: *mut c_void,
    }

    type ZSTDCreateCCtx = unsafe extern "C" fn() -> *mut c_void;
    type ZSTDFreeCCtx = unsafe extern "C" fn(*mut c_void) -> c_int;
    type ZSTDCompressCCtx = unsafe extern "C" fn(
        *mut c_void,
        *mut c_void,
        c_ulonglong,
        *const c_void,
        c_ulonglong,
        c_int,
    ) -> c_ulonglong;
    type ZSTDIsError = unsafe extern "C" fn(c_ulonglong) -> c_int;
    type ZSTDGetErrorName = unsafe extern "C" fn(c_ulonglong) -> *const u8;

    type ZSTDCreateDCtx = unsafe extern "C" fn() -> *mut c_void;
    type ZSTDFreeDCtx = unsafe extern "C" fn(*mut c_void) -> c_int;
    type ZSTDDecompressDCtx = unsafe extern "C" fn(
        *mut c_void,
        *mut c_void,
        c_ulonglong,
        *const c_void,
        c_ulonglong,
    ) -> c_ulonglong;

    type ZSTDGetFrameContentSize = unsafe extern "C" fn(*const c_void, c_ulonglong) -> c_ulonglong;

    impl ZSTD {
        pub fn new() -> Result<Self, String> {
            unsafe {
                let lib_name = CString::new("libzstd.so.1").unwrap();
                let lib = super::libc_bindings::dlopen(lib_name.as_ptr() as *const u8, super::libc_bindings::RTLD_LAZY | super::libc_bindings::RTLD_GLOBAL);
                if lib.is_null() {
                    return Err("Failed to load libzstd".to_string());
                }
                Ok(ZSTD { lib })
            }
        }

        pub fn compress(&self, data: &[u8], level: i32) -> Result<Vec<u8>, String> {
            unsafe {
                let create_fn: ZSTDCreateCCtx = std::mem::transmute(
                    super::libc_bindings::dlsym(self.lib, CString::new("ZSTD_createCCtx").unwrap().as_ptr() as *const u8)
                );
                let compress_fn: ZSTDCompressCCtx = std::mem::transmute(
                    super::libc_bindings::dlsym(self.lib, CString::new("ZSTD_compressCCtx").unwrap().as_ptr() as *const u8)
                );
                let free_fn: ZSTDFreeCCtx = std::mem::transmute(
                    super::libc_bindings::dlsym(self.lib, CString::new("ZSTD_freeCCtx").unwrap().as_ptr() as *const u8)
                );
                let is_error_fn: ZSTDIsError = std::mem::transmute(
                    super::libc_bindings::dlsym(self.lib, CString::new("ZSTD_isError").unwrap().as_ptr() as *const u8)
                );
                let get_error_fn: ZSTDGetErrorName = std::mem::transmute(
                    super::libc_bindings::dlsym(self.lib, CString::new("ZSTD_getErrorName").unwrap().as_ptr() as *const u8)
                );

                let cctx = create_fn();
                if cctx.is_null() {
                    return Err("Failed to create context".to_string());
                }

                let mut output = vec![0u8; data.len() + 1000];
                let result = compress_fn(
                    cctx,
                    output.as_mut_ptr() as *mut c_void,
                    output.len() as c_ulonglong,
                    data.as_ptr() as *const c_void,
                    data.len() as c_ulonglong,
                    level,
                );

                free_fn(cctx);

                if is_error_fn(result) != 0 {
                    let err_name = get_error_fn(result);
                    let error_str = CStr::from_ptr(err_name as *const i8).to_string_lossy();
                    return Err(format!("Compression error: {}", error_str));
                }

                output.truncate(result as usize);
                Ok(output)
            }
        }

        pub fn decompress(&self, data: &[u8]) -> Result<Vec<u8>, String> {
            unsafe {
                let create_fn: ZSTDCreateDCtx = std::mem::transmute(
                    super::libc_bindings::dlsym(self.lib, CString::new("ZSTD_createDCtx").unwrap().as_ptr() as *const u8)
                );
                let decompress_fn: ZSTDDecompressDCtx = std::mem::transmute(
                    super::libc_bindings::dlsym(self.lib, CString::new("ZSTD_decompressDCtx").unwrap().as_ptr() as *const u8)
                );
                let free_fn: ZSTDFreeDCtx = std::mem::transmute(
                    super::libc_bindings::dlsym(self.lib, CString::new("ZSTD_freeDCtx").unwrap().as_ptr() as *const u8)
                );
                let is_error_fn: ZSTDIsError = std::mem::transmute(
                    super::libc_bindings::dlsym(self.lib, CString::new("ZSTD_isError").unwrap().as_ptr() as *const u8)
                );
                let get_error_fn: ZSTDGetErrorName = std::mem::transmute(
                    super::libc_bindings::dlsym(self.lib, CString::new("ZSTD_getErrorName").unwrap().as_ptr() as *const u8)
                );
                let get_frame_size_fn: ZSTDGetFrameContentSize = std::mem::transmute(
                    super::libc_bindings::dlsym(self.lib, CString::new("ZSTD_getFrameContentSize").unwrap().as_ptr() as *const u8)
                );

                let dctx = create_fn();
                if dctx.is_null() {
                    return Err("Failed to create context".to_string());
                }

                let frame_size = get_frame_size_fn(
                    data.as_ptr() as *const c_void,
                    data.len() as c_ulonglong,
                );

                let output_size = if frame_size == u64::MAX || frame_size == 0 {
                    data.len() * 4
                } else {
                    frame_size as usize
                };

                let mut output = vec![0u8; output_size];
                let result = decompress_fn(
                    dctx,
                    output.as_mut_ptr() as *mut c_void,
                    output.len() as c_ulonglong,
                    data.as_ptr() as *const c_void,
                    data.len() as c_ulonglong,
                );

                free_fn(dctx);

                if is_error_fn(result) != 0 {
                    let err_name = get_error_fn(result);
                    let error_str = CStr::from_ptr(err_name as *const i8).to_string_lossy();
                    return Err(format!("Decompression error: {}", error_str));
                }

                output.truncate(result as usize);
                Ok(output)
            }
        }
    }
}

fn main() -> Result<(), Box<dyn std::error::Error>> {
    let args: Vec<String> = env::args().collect();

    let mut opts = Options::default();
    let mut input_files: Vec<String> = Vec::new();
    let mut i = 1;

    while i < args.len() {
        let arg = &args[i];

        match arg.as_str() {
            "--version" | "-V" => {
                println!("*** Zstandard CLI (64-bit) v1.6.0, by Yann Collet ***");
                return Ok(());
            }
            "-h" | "--help" | "-H" => {
                print_help();
                return Ok(());
            }
            "-d" | "--decompress" => opts.decompress = true,
            "-c" | "--stdout" => opts.to_stdout = true,
            "-k" | "--keep" => opts.keep = true,
            "--rm" => opts.keep = false,
            "-f" | "--force" => opts.force = true,
            "-t" => opts.test_only = true,
            "-l" => opts.list_info = true,
            "-v" | "--verbose" => opts.verbose += 1,
            "-q" | "--quiet" => opts.quiet += 1,
            "-o" => {
                i += 1;
                if i < args.len() {
                    opts.output_file = Some(args[i].clone());
                }
            }
            "-D" => {
                i += 1;
                if i < args.len() {
                    opts.dict_file = Some(args[i].clone());
                }
            }
            arg if arg.starts_with("-") && arg.len() >= 2 && arg[1..].chars().all(|c| c.is_ascii_digit()) => {
                opts.compression_level = arg[1..].parse()?;
            }
            _ => input_files.push(arg.clone()),
        }

        i += 1;
    }

    if opts.list_info {
        let zstd = zstd_dll::ZSTD::new()?;
        for file in &input_files {
            list_file_info(file, &zstd)?;
        }
        return Ok(());
    }

    if opts.test_only {
        let zstd = zstd_dll::ZSTD::new()?;
        for file in &input_files {
            test_file(file, &zstd)?;
        }
        return Ok(());
    }

    let has_input_files = !input_files.is_empty() && input_files[0] != "-";

    let zstd = zstd_dll::ZSTD::new()?;

    if opts.to_stdout {
        if has_input_files {
            for file in &input_files {
                if opts.decompress {
                    decompress_file_to_stdout(file, &zstd)?;
                } else {
                    compress_file_to_stdout(file, opts.compression_level, &zstd)?;
                }
            }
        } else {
            if opts.decompress {
                decompress_stdin_to_stdout(&zstd)?;
            } else {
                compress_stdin_to_stdout(opts.compression_level, &zstd)?;
            }
        }
    } else if let Some(output) = &opts.output_file {
        if input_files.is_empty() || input_files[0] == "-" {
            if opts.decompress {
                decompress_stdin_to_file(output, &zstd)?;
            } else {
                compress_stdin_to_file(output, opts.compression_level, &zstd)?;
            }
        } else if input_files.len() == 1 {
            if opts.decompress {
                decompress_file_to_file(&input_files[0], output, &zstd)?;
            } else {
                compress_file_to_file(&input_files[0], output, opts.compression_level, &zstd)?;
            }
        } else {
            return Err("Cannot use -o with multiple input files".into());
        }
    } else {
        if has_input_files {
            for file in &input_files {
                if opts.decompress {
                    let output_name = if file.ends_with(".zst") {
                        file[..file.len() - 4].to_string()
                    } else {
                        format!("{}.decompressed", file)
                    };
                    decompress_file_to_file(file, &output_name, &zstd)?;
                    if !opts.keep {
                        fs::remove_file(file)?;
                    }
                } else {
                    let output_name = format!("{}.zst", file);
                    compress_file_to_file(file, &output_name, opts.compression_level, &zstd)?;
                    if !opts.keep {
                        fs::remove_file(file)?;
                    }
                }
            }
        } else {
            if opts.decompress {
                decompress_stdin_to_stdout(&zstd)?;
            } else {
                compress_stdin_to_stdout(opts.compression_level, &zstd)?;
            }
        }
    }

    Ok(())
}

